-- Atualiza somente textos e regras descritivas dos 25 códigos existentes.
-- Não altera códigos, IDs, preços, status, visibilidade, contratos, solicitações ou instalações.

with catalog_copy(code, summary, description, integration_requirements, activation_rules, disable_rules) as (
  values
  ('novaes_fideliza', 'Programa de pontos, recompensas e benefícios para clientes recorrentes.', 'Configure como clientes acumulam pontos em pedidos elegíveis, acompanhe saldo e histórico, e permita resgates com regras claras. O saldo deve ser atualizado junto ao pedido de forma segura, sem duplicar pontos em reprocessamentos.', 'Integrar pedidos elegíveis e identidade do cliente; definir regras de acúmulo, expiração e resgate; registrar lançamentos idempotentes; validar saldo e resgate no servidor; isolar todos os registros por store_id e manter auditoria.', 'Exigir módulo ready, compatibilidade, instalação técnica disponível, contratação ativa e confirmação comercial do Master. O resgate deve validar saldo e regras no backend; check-in sozinho não ativa.', 'Ao suspender ou revogar, bloquear novos acúmulos/resgates e todas as rotas/APIs. Preservar saldos e extrato para análise; não apagar pontos nem permitir saldo negativo.'),
  ('novaes-os', 'Ordens de serviço com etapas, responsáveis, prazos e histórico do atendimento.', 'Abra uma ordem de serviço vinculada ao cliente e ao item atendido, acompanhe status e responsável, registre observações e consulte o histórico. Adequado a oficinas e prestadores; não substitui sistema fiscal ou de estoque.', 'Definir categorias e fluxo de status; vincular cliente e serviço sem cruzar lojas; registrar mudanças e responsáveis; proteger anexos; aplicar RLS por store_id e testar transições no backend.', 'Exigir módulo ready, compatibilidade, instalação técnica disponível, contratação ativa e confirmação comercial do Master. Validar cada transição no servidor.', 'Bloquear criação, edição, anexos e transições quando não ativo; preservar ordens e histórico em modo somente leitura para exportação/administração autorizada.'),
  ('novaes-mesa', 'Pedidos por QR Code associados a mesas e enviados ao painel da loja.', 'Gere QR Codes por mesa, permita ao consumidor abrir o cardápio e enviar um pedido, e acompanhe a mesa e os itens no painel. Confirme antes da implementação como os pedidos entram na fila atual para evitar duplicidade.', 'Usar identificadores não previsíveis ou tokens rotacionáveis; validar disponibilidade/preço no servidor; registrar mesa e pedido atomicamente; impedir pedido duplicado; respeitar horários, catálogo e RLS da loja.', 'Exigir módulo ready, compatibilidade, instalação técnica disponível e contratação ativa. Confirmar pedido e preço no servidor; QR não autoriza acesso administrativo.', 'Ao revogar, bloquear novos pedidos QR e operação de mesa. Manter pedidos já aceitos e seu histórico; permitir concluir operações em andamento segundo política definida pela loja.'),
  ('novaes-gift', 'Cartões-presente com código, saldo e resgates registrados.', 'Permita vender ou emitir cartões-presente, consultar saldo e aplicar resgates parciais ou totais. Cada movimentação deve ter extrato e proteção contra reutilização simultânea.', 'Gerar códigos com entropia adequada e armazenar verificador quando possível; manter ledger imutável; aplicar débito de saldo transacionalmente; definir validade, cancelamento e reembolso; usar store_id e RLS.', 'Exigir módulo ready, compatibilidade, instalação técnica disponível e contratação ativa. Validar código, saldo, status e pedido de forma transacional no backend.', 'Bloquear emissão e resgate após suspensão. Preservar saldos, movimentações e obrigação de honrar cartões já vendidos conforme condições comerciais; não apagar histórico.'),
  ('novaes-tv', 'Vitrine digital para exibir produtos e campanhas em telas da loja.', 'Monte uma apresentação de produtos, preços e campanhas para televisores, com atualização controlada pelo painel. A tela pública deve ser somente leitura e não expor dados internos, clientes ou credenciais.', 'Criar visualização pública limitada, token por tela revogável e sem acesso administrativo; definir atualização/cache e mídia permitida; respeitar disponibilidade do catálogo e direitos dos arquivos.', 'Exigir módulo ready, compatibilidade e contratação ativa; emitir somente credencial pública de escopo mínimo para cada tela.', 'Revogar tokens e bloquear novas leituras quando suspenso; preservar playlists e configurações para reativação ou exportação.'),
  ('novaes-whatsapp-notify', 'Notificações transacionais de pedidos pelo WhatsApp, conforme consentimento e provedor conectado.', 'Envie mensagens configuradas para eventos como pedido recebido, confirmação e atualização de status. O conteúdo, opt-in do destinatário, limites e custos do provedor precisam ser definidos antes da ativação.', 'Usar provedor aprovado; manter tokens somente em backend; validar opt-in, templates e limites; usar fila, retries e idempotência; registrar entrega/erro sem gravar segredos; oferecer opt-out.', 'Exigir módulo ready, contratação ativa, provedor configurado no servidor, consentimento aplicável e teste de entrega. Não enviar mensagens sem opt-in ou por check-in apenas.', 'Interromper novos envios e jobs ao suspender; não reenviar filas antigas automaticamente sem política; preservar logs minimizados e permitir revogação de credenciais.'),
  ('whatsapp-oficial-activation', 'Serviço de configuração inicial da conexão oficial de WhatsApp.', 'Solicitação de onboarding técnico, validação da conta e configuração do canal oficial. A aprovação do serviço não inclui automaticamente mensalidade do provedor, franquia ou custo por mensagem.', 'Tratar como serviço operacional com checklist, escopo, responsável, autorização do titular e registro de conclusão; nunca pedir senha da conta; usar OAuth/procedimento oficial e guardar tokens em backend seguro.', 'Ativar como serviço somente após aprovação do escopo, condições comerciais e confirmação da execução pelo Master; não exigir check-in de código de módulo quando a instalação for serviço externo.', 'Encerrar acesso técnico e revogar credenciais temporárias ao concluir ou cancelar; preservar comprovantes de atendimento sem armazenar segredo.'),
  ('novaes-print-connect', 'Conexão de pedidos com impressoras e fluxos de impressão da loja.', 'Encaminhe comprovantes ou comandas para impressoras configuradas, com seleção de setores e acompanhamento de falhas. A impressão deve ser recuperável sem duplicar pedidos.', 'Definir modelo de impressora e agente; proteger pareamento; implementar fila, idempotência, retry e sinalização de falha; não expor IP/credenciais; validar autorização e loja em cada configuração.', 'Exigir módulo ready, contratação ativa, hardware compatível e teste de impressão autorizado. Disponibilidade da tela não equivale a integração de hardware funcional.', 'Parar novos trabalhos ao suspender; manter fila/histórico e permitir reprocessamento administrativo controlado, sem imprimir pedidos duplicados.'),
  ('custom-integrations', 'Análise e orçamento de integração com serviços ou equipamentos externos.', 'Descreva o serviço que deseja conectar e receba avaliação de compatibilidade, escopo, prazo e preço. A solicitação não cria conexão nem autoriza compartilhamento de credenciais.', 'Coletar apenas requisitos não secretos; documentar API, responsável, permissões e custos do fornecedor; definir escopo e critérios de aceite antes de implementar.', 'Exigir aprovação de escopo e orçamento pelo Master. Qualquer integração executável deve ter implementação, credenciais server-side e autorização separada.', 'Desativar jobs/chaves do conector quando revogado; preservar logs técnicos minimizados e configurações não secretas.'),
  ('novaes-promo', 'Campanhas promocionais com período, produtos elegíveis e divulgação no site.', 'Planeje e publique campanhas, banners e ofertas com início/fim e produtos participantes. Este item cobre a comunicação da promoção; descontos por código, regras de uso e validação no checkout só existem se implementados e descritos como módulo específico.', 'Definir público, período, elegibilidade e canais; validar preços no backend; evitar campanhas vencidas; registrar alterações; manter conteúdo tenant-scoped. Não assumir que inclui cupons.', 'Exigir módulo ready, contratação ativa e validação no servidor das regras aplicadas a pedidos. O Master precisa revisar a descrição comercial antes de vender recursos não implementados.', 'Ocultar campanhas e bloquear novas aplicações ao suspender; preservar relatórios e histórico de campanhas.'),
  ('novaes-finance', 'Visões operacionais de receitas, despesas e conciliação da loja.', 'Organize indicadores operacionais, lançamentos e conferências com filtros e relatórios. Deixe explícitos os dados de origem e as limitações; não se apresenta como contabilidade, escrituração fiscal ou aconselhamento financeiro.', 'Definir fontes e fórmulas; controlar acesso por função; auditar ajustes manuais; reconciliar totais e períodos; não enviar dados financeiros ao Master sem finalidade/autorização; aplicar RLS por loja.', 'Exigir módulo ready, contratação ativa e autorização por papel para cada operação financeira. Confirmar fórmulas e origem antes de exibir valores.', 'Bloquear consultas e alterações financeiras quando inativo; preservar lançamentos, relatórios e trilha de auditoria.'),
  ('novaes-equipe', 'Cadastro de usuários da equipe com papéis e permissões do painel da loja.', 'Convide funcionários, atribua permissões por função e remova acessos quando necessário. Cada colaborador deve usar identidade própria; não compartilhe a conta do proprietário.', 'Integrar com Auth/convites seguros; impor menor privilégio; validar autorização no backend para cada ação; auditar convites e alterações de papel; não confiar em papel vindo do navegador.', 'Exigir módulo ready e contratação ativa. Apenas owner/admin autorizado pode convidar e alterar papéis; nunca permitir conceder papel MASTER.', 'Revogar sessões/vínculos ao remover membro; manter registros administrativos mínimos; bloquear imediatamente operações sem papel ativo.'),
  ('novaes-insights', 'Relatórios de vendas, produtos e comportamento com métricas explicadas.', 'Apresente tendências, horários de pico, produtos mais vendidos e evolução por período com fórmulas transparentes. Os gráficos devem derivar de dados da própria loja e indicar quando uma amostra é insuficiente.', 'Definir métricas e timezone; consultar apenas dados da loja; proteger exportações; evitar exposição de PII; validar agregações e intervalos; aplicar RLS e limites de consulta.', 'Exigir módulo ready e contratação ativa. Explicar origem/fórmula dos indicadores e conferir resultados com dados de teste.', 'Bloquear painéis e exportações quando suspenso; preservar agregados e histórico conforme retenção aprovada.'),
  ('novaes-marketing', 'Planejamento de campanhas e acompanhamento de canais de divulgação.', 'Organize campanhas, links rastreáveis, calendário e resultados por canal. Diferencie este módulo da criação de promoções no Novaes Promo e das mensagens transacionais do WhatsApp Notify.', 'Definir eventos e atribuição sem rastreamento excessivo; respeitar consentimento e privacidade; proteger tokens de canais; documentar limitações de atribuição e custos de mídia.', 'Exigir módulo ready, contratação ativa e credenciais do canal configuradas com escopo mínimo no backend.', 'Parar campanhas/jobs e revogar conexões quando suspenso; preservar relatórios não sensíveis.'),
  ('domain-setup', 'Serviço de configuração e validação de domínio próprio.', 'A NovaesWeb auxilia a apontar e validar o domínio informado. Registro, renovação e hospedagem de terceiros podem ter custos separados, informados antes do serviço.', 'Confirmar titularidade do domínio; registrar DNS esperado e janela de propagação; nunca pedir senha do registrador; fornecer instruções e validar HTTPS após autorização.', 'Tratar como serviço sob escopo: aprovar domínio, custo e acesso necessário; não exige contrato de módulo nem check-in de software.', 'Ao finalizar, remover acessos temporários e entregar configuração/documentação; a expiração do serviço não deve derrubar um domínio já configurado.'),
  ('custom-training', 'Treinamento individual para uso das funções existentes no sistema.', 'Agende uma sessão orientada ao painel e aos fluxos que já estão disponíveis para a loja. Informe duração, formato e escopo antes da contratação.', 'Confirmar participantes, agenda, duração e materiais; não usar dados reais de clientes na demonstração sem necessidade.', 'Ativar como serviço após confirmação de escopo, agenda e condições comerciais pelo Master; não requer instalação de módulo.', 'Concluir acesso temporário após a sessão e preservar somente o registro administrativo mínimo.'),
  ('one_off-adjustment', 'Pedido de ajuste pontual em conteúdo ou configuração existente.', 'Descreva o ajuste desejado para avaliação. A equipe confirma escopo, prazo, compatibilidade e preço antes de iniciar; mudanças fora do pedido exigem nova aprovação.', 'Registrar solicitação, ambiente, critérios de aceite e autorização; avaliar backup/rollback; não executar código arbitrário enviado pelo cliente.', 'Aprovar como serviço por solicitação e escopo; não marcar como módulo instalado nem criar feature gate permanente.', 'Encerrar após aceite ou cancelamento; documentar reversão e manter histórico do pedido.'),
  ('banner-update', 'Serviço de atualização de banners e imagens promocionais do site.', 'Solicite troca ou criação de banner com dimensões, período e destino informados. A publicação só ocorre após aprovação do material e conferência em celular e desktop.', 'Validar formatos, dimensões, acessibilidade, direitos de uso e destino do link; otimizar arquivos; ter backup do banner anterior.', 'Aprovar como serviço pontual, com material e escopo aceitos; não requer instalação de módulo.', 'Reverter ao material anterior quando solicitado e preservar histórico de publicação.'),
  ('product-registration-pack-10', 'Serviço de cadastro de até dez produtos no catálogo da loja.', 'A equipe cadastra até 10 itens a partir das informações e imagens fornecidas. Variações, integrações e tratamento de fotos podem exigir escopo adicional.', 'Usar modelo aprovado de dados; validar nome, preço, disponibilidade, variantes e imagens; confirmar os itens com o lojista antes de publicar.', 'Ativar como serviço após recebimento do material completo e confirmação das condições; não requer módulo instalado.', 'Não remover produtos cadastrados ao encerrar o serviço; correções posteriores seguem novo escopo.'),
  ('extraordinary-support', 'Atendimento pontual fora do suporte incluído no plano.', 'Solicite apoio para um incidente ou dúvida específica; informe impacto, horário e resultado esperado. Prazo e disponibilidade são confirmados antes da cobrança.', 'Classificar urgência e escopo; nunca solicitar senha ou segredo por mensagem; registrar consentimento e ações realizadas.', 'Aprovar como atendimento avulso segundo escopo e disponibilidade, sem ativação de módulo.', 'Encerrar acessos temporários após o atendimento e manter histórico sem segredos.'),
  ('custom-development', 'Desenvolvimento de função exclusiva, estimado após levantamento.', 'Descreva a necessidade. A NovaesWeb avalia impacto, dependências, prazo, critérios de aceite e valor antes de iniciar. Não é promessa de função já disponível.', 'Fazer descoberta, estimativa e critérios de aceite; revisar segurança, migrações, compatibilidade e manutenção; separar proposta de implementação.', 'Exigir proposta e autorização expressas antes de código, migração ou publicação. Só cadastrar como módulo reutilizável se isso for aprovado separadamente.', 'Definir suporte, manutenção e rollback no escopo; preservar dados e manter histórico de entrega.'),
  ('novaes-backup-plus', 'Proposta de proteção e recuperação ampliada dos dados da loja.', 'Pode incluir retenção adicional, cópias exportáveis e processo de restauração conforme infraestrutura disponível. Não prometa frequência, retenção ou recuperação até validar e testar o mecanismo real.', 'Definir RPO/RTO, escopo, retenção, criptografia, localização, custos e testes de restauração; evitar duplicar o backup nativo sem benefício demonstrável.', 'Manter planned até teste de restauração e revisão operacional. Ativar somente com escopo, infraestrutura e contratação confirmados.', 'Suspender novas rotinas sem apagar cópias necessárias ao período contratado; cumprir retenção e exclusão acordadas e registrar restaurações.'),
  ('novaes-multiusuario', 'Expansão de usuários e controles de acesso para a equipe da loja.', 'Permite ampliar o número de colaboradores e organizar permissões por função, mantendo uma conta por pessoa. Limites e papéis devem ser apresentados antes da contratação.', 'Definir limites de assentos, convites, papéis e trilha de auditoria; aplicar autorização server-side; impedir elevação de privilégio; testar revogação de sessão.', 'Manter planned até que gestão de equipe e limites sejam implementados e testados. Requer contratação ativa e owner/admin autorizado.', 'Ao suspender, bloquear novos convites e acessos acima do limite contratado segundo política comunicada; não apagar registros de auditoria.'),
  ('novaes-multiunidade', 'Gestão de filiais/unidades sob uma organização, com separação por unidade.', 'Permite configurar unidades, operação e relatórios próprios e, se aprovado, uma visão consolidada. Cada unidade precisa de identificador e permissões claramente separados.', 'Projetar branch_id/unit_id e constraints compostas; validar acesso por unidade em consultas, gravações e arquivos; decidir catálogo, estoque, pedidos e faturamento compartilhados ou separados.', 'Manter planned até auditoria multi-tenant e testes de isolamento por organização/unidade. Não usar store_id de outra loja para representar filial.', 'Revogar apenas a unidade autorizada, preservar dados e históricos e impedir acesso cruzado após alterações de membership.'),
  ('novaes-import', 'Importação assistida de produtos e dados a partir de arquivos compatíveis.', 'Importe planilhas com prévia, validação e relatório de erros antes de gravar. O sistema deve mostrar duplicidades e permitir confirmar atualização ou inserção.', 'Validar tamanho/tipo de arquivo e conteúdo; limitar colunas; prevenir fórmulas perigosas em exportações; processar em lotes idempotentes; confirmar tenant e permissões no servidor.', 'Manter planned até testar formatos, rollback e prevenção de duplicação. Exigir contratação ativa e confirmação explícita antes da gravação em lote.', 'Interromper novas importações ao suspender; não desfazer silenciosamente lotes existentes; preservar relatório para suporte.')
)
update public.addon_catalog c
set summary = d.summary,
    description = d.description,
    integration_requirements = d.integration_requirements,
    activation_rules = d.activation_rules,
    disable_rules = d.disable_rules,
    updated_at = now()
from catalog_copy d
where c.code = d.code;
